// src/main/java/com/acme/GreetMojo.java in a project with <packaging>maven-plugin</packaging>
package com.acme;
import org.apache.maven.plugin.*;
import org.apache.maven.plugins.annotations.*;
import org.apache.maven.project.MavenProject;
import java.nio.file.*;
@Mojo(name = "greet", defaultPhase = LifecyclePhase.GENERATE_RESOURCES, threadSafe = true)
public class GreetMojo extends AbstractMojo {
    @Parameter(property = "greet.name", defaultValue = "World")
    private String name;
    @Parameter(defaultValue = "${project.build.directory}/greeting.txt", required = true)
    private Path output;
    @Parameter(defaultValue = "${project}", readonly = true)
    private MavenProject project;
    @Override
    public void execute() throws MojoExecutionException {
        try {
            Files.createDirectories(output.getParent());
            Files.writeString(output, "Hello, " + name + " from " + project.getArtifactId());
            getLog().info("Wrote " + output);
        } catch (java.io.IOException e) {
            throw new MojoExecutionException("could not write greeting", e);
        }
    }
}
// consumer: <plugin><groupId>com.acme</groupId><artifactId>greet-maven-plugin</artifactId>
//   <version>1.0.0</version><executions><execution><goals><goal>greet</goal></goals></execution></executions></plugin>
// $ mvn generate-resources -Dgreet.name=Ada   -> [INFO] Wrote .../target/greeting.txt
